        scene.add(dirLight);

        // Camera position
        camera.position.set(0, 15, 30);
        controls.update();

        // Building exterior
        const buildingGeo = new THREE.BoxGeometry(BUILDING_WIDTH, FLOOR_HEIGHT * FLOOR_COUNT + 2, BUILDING_DEPTH);
        const buildingMat = new THREE.MeshPhongMaterial({ color: 0x8B9DC3 });
        const building = new THREE.Mesh(buildingGeo, buildingMat);
        scene.add(building);

        // Shafts (two vertical shafts)
        for (let i = 0; i < FLOOR_COUNT + 2; i++) {
            const shaftY = -FLOOR_HEIGHT * (i + 1) + 3;
            const shaftGeo = new THREE.BoxGeometry(SHAFT_WIDTH, FLOOR_HEIGHT, SHAFT_DEPTH);
            const shaftMat = new THREE.MeshPhongMaterial({ color: 0xCCCCCC });
            scene.add(new THREE.Mesh(shaftGeo, shaftMat).position.set(-SHAFT_WIDTH/2 - 1.5, shaftY, BUILDING_DEPTH/2 - 3));
            scene.add(new THREE.Mesh(shaftGeo, shaftMat).position.set(SHAFT_WIDTH/2 + 1.5, shaftY, BUILDING_DEPTH/2 - 3));
        }

        // Elevator car group
        elevatorCar = new THREE.Group();

        // Car body
        const carBodyGeo = new THREE.BoxGeometry(3.2, 3, 2);
        const carBodyMat = new THREE.MeshPhongMaterial({ color: 0xEEEEEE });
        const carBody = new THREE.Mesh(carBodyGeo, carBodyMat);
        elevatorCar.add(carBody);

        // Car interior (darker)
        const interiorGeo = new THREE.BoxGeometry(3.15, 2.8, 1.95);
        const interiorMat = new THREE.MeshPhongMaterial({ color: 0xCCCCCC });
        const interior = new THREE.Mesh(interiorGeo, interiorMat);
        elevatorCar.add(interior);

        // Doors (left and right)
        leftDoor = createDoor(1.8, 2.5, 0.1, -1.4, -0.5, -90, false);
        rightDoor = createDoor(1.8, 2.5, 0.1, 1.4, -0.5, -90, true);

        elevatorCar.leftDoor = leftDoor;
        elevatorCar.rightDoor = rightDoor;

        // Attach doors to car at the correct position
        elevatorCar.attach(leftDoor);
        elevatorCar.attach(rightDoor);

        scene.add(elevatorCar);

        // Floor indicators inside building
        for (let i = 0; i < FLOOR_COUNT + 1; i++) {
            const floorY = -FLOOR_HEIGHT * (i + 1) + FLOOR_HEIGHT / 2 + 1.5;

            // Floor slab
            const slabGeo = new THREE.BoxGeometry(BUILDING_WIDTH, 0.3, BUILDING_DEPTH);
            const slabMat = new THREE.MeshPhongMaterial({ color: 0x9999AA });
            scene.add(new THREE.Mesh(slabGeo, slabMat).position.set(0, floorY, 0));

            // Floor number indicators
            if (i < FLOOR_COUNT) {
                const floorLabel = new THREE.Mesh(
                    new THREE.CylinderGeometry(1.5, 1.5, 0.1, 32),
                    new THREE.MeshPhongMaterial({ color: 0xFFFFFF })
                );
                scene.add(floorLabel);

                const floorText = document.createElement('div');
                floorText.textContent = (i + 1) + 'F';
                floorText.style.position = 'absolute';
                floorText.style.left = '50%';
                floorText.style.top = '40px';
                floorText.style.transform = 'translateX(-50%)';
                floorText.style.color = '#fff';
                floorText.style.fontFamily = 'sans-serif';
                floorText.style.fontSize = '16px';
                document.body.appendChild(floorText);

                const indicatorGeo = new THREE.SphereGeometry(0.3, 16, 16);
                const indicatorMat = new THREE.MeshPhongMaterial({ color: i === FLOOR_COUNT - 1 ? 0xFFD700 : (i % 2 ? 0xFFFFFF : 0x999999) });
                const sphere = new THREE.Mesh(indicatorGeo, indicatorMat);
                scene.add(sphere.position.set(0, floorY + 0.55, BUILDING_DEPTH / 2 - 3));
            }

            // Side shaft walls (inner vertical surfaces)
        }

        return elevatorCar;
    }

    function createDoor(width, height, depth, xPos, yBase, rotationY, isRight) {
        const doorGroup = new THREE.Group();
        const doorGeo = new THREE.BoxGeometry(width, height, depth);
        const doorMat = new THREE.MeshPhongMaterial({ color: 0x555555 });
        const door = new THREE.Mesh(doorGeo, doorMat);
