        person.position.set(-SHAFT_WIDTH / 2 - 1.5, -0.5, BUILDING_DEPTH / 2 - 3);
        scene.add(person);

        // Person walks toward elevator door over a few frames
        let personZ = person.position.z;

        function walkToElevator() {
            if (person.userData.isWalking) return;

            const targetY = FLOOR_HEIGHT / 2 - 0.5 + Math.sin(Date.now() * 0.003) * 0.2;
            person.position.y += (targetY - person.position.y) * 0.1;

