                leftDoor.rotation.y += Math.PI / 2 * 0.15;
                rightDoor.rotation.y -= Math.PI / 2 * 0.15;

                return;
            }

            personZ += PERSON_MOVE_SPEED * 0.03;
            person.userData.isWalking = true;
        }

        walkToElevator();
    }

    // Auto-start with DOMContentLoaded pattern
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', startSimulation);
    } else {
        startSimulation();
    }

